class _ViewerLocalizationsDelegate
    extends LocalizationsDelegate<ViewerLocalizations> {
  const _ViewerLocalizationsDelegate();

  @override
  Future<ViewerLocalizations> load(Locale locale) {
    return SynchronousFuture<ViewerLocalizations>(
      lookupViewerLocalizations(locale),
    );
  }

  @override
  bool isSupported(Locale locale) =>
      <String>['en', 'fa'].contains(locale.languageCode);

  @override
  bool shouldReload(_ViewerLocalizationsDelegate old) => false;
}

ViewerLocalizations lookupViewerLocalizations(Locale locale) {
  // Lookup logic when only language code is specified.
  switch (locale.languageCode) {
    case 'en':
      return ViewerLocalizationsEn();
    case 'fa':
      return ViewerLocalizationsFa();
  }

  throw FlutterError(
    'ViewerLocalizations.delegate failed to load unsupported locale "$locale". This is likely '
    'an issue with the localizations generation tool. Please file an issue '
    'on GitHub with a reproducible sample app and the gen-l10n configuration '
    'that was used.',
  );
}
